/* ============================================================================
   Horizon Hotel & Resort - Datos de negocio simulados (historia coherente)
   ----------------------------------------------------------------------------
   BORRA y vuelve a cargar: Pisos, TiposHabitacion, Habitaciones, Huespedes,
   Reservas, Acompanantes, Pagos y ConfiguracionHotel, más los eventos de
   negocio de la Bitácora (Reservas, Habitaciones, Huéspedes, Pagos, Config).
   NO toca Users, Roles, Familias, Permisos ni los eventos de login/usuarios.

   Todas las fechas son RELATIVAS al día en que se ejecuta (@Hoy), así el
   estado de cada reserva es coherente con la fecha real:
     - 477 finalizadas (check-in + check-out, pagadas)
     - 8 en curso (check-in hecho, habitación Ocupada)
     - 100 confirmadas a futuro (algunas ingresan hoy)
     - 79 canceladas (17 no-show procesados automáticamente)
     - 40 renovaciones (el excedente se cobró en el check-out, o queda como saldo si siguen en curso)
   842 huéspedes, 405 acompañantes registrados en check-in, 703 pagos.

   Flujo simulado (igual que en la aplicación):
     Registrar reserva -> Pago del total (Efectivo / Tarjeta / Transferencia)
     Check-in (el día de ingreso, se cargan los acompañantes) -> Habitación Ocupada
     Renovación -> sube MontoTotal, MontoOriginal no cambia
     Check-out -> se cobra el saldo pendiente -> Habitación En limpieza -> Disponible
     Cancelación / no-show -> el pago queda registrado (monto anulado del dashboard)

   Usuarios que operan: DNI 46898868 (Nahu) y 12345678 (Maximo). Si no existen,
   se usan los dos primeros usuarios de la tabla Users.

   IMPORTANTE: al terminar, entrar con un administrador y RECALCULAR los
   dígitos verificadores (DV); si no, la verificación de integridad va a fallar.
   ============================================================================ */
USE [TP_Ing_Soft];
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

DECLARE @Hoy DATE = CAST(GETDATE() AS DATE);
DECLARE @B DATETIME = CAST(@Hoy AS DATETIME);   -- hoy 00:00; los horarios se suman en segundos

DECLARE @DniA INT = 46898868, @DniB INT = 12345678, @UserA NVARCHAR(50), @UserB NVARCHAR(50);
SELECT @UserA = Username FROM Users WHERE DNI = @DniA;
SELECT @UserB = Username FROM Users WHERE DNI = @DniB;
IF @UserA IS NULL SELECT TOP 1 @DniA = DNI, @UserA = Username FROM Users ORDER BY DNI;
IF @UserB IS NULL SELECT TOP 1 @DniB = DNI, @UserB = Username FROM Users WHERE DNI <> @DniA ORDER BY DNI;
IF @UserB IS NULL SELECT @DniB = @DniA, @UserB = @UserA;
IF @UserA IS NULL BEGIN RAISERROR('No hay usuarios cargados en la tabla Users.', 16, 1); ROLLBACK; RETURN; END

/* ---------------------------------------------------------------- 1. Borrado */
DELETE FROM [dbo].[Acompanantes];
DELETE FROM [dbo].[Pagos];
DELETE FROM [dbo].[Reservas];
DELETE FROM [dbo].[Huespedes];
DELETE FROM [dbo].[Habitaciones];
DELETE FROM [dbo].[TiposHabitacion];
DELETE FROM [dbo].[Pisos];
DELETE FROM [dbo].[ConfiguracionHotel];
-- Eventos de negocio: 3 Reservas, 4 Habitaciones, 5 Huéspedes, 6 Pagos, 7 Configuración
DELETE FROM [dbo].[Bitacora] WHERE [Modulo] IN (3, 4, 5, 6, 7);

/* ---------------------------------------------------------------- 2. Configuración y catálogo */
SET IDENTITY_INSERT [dbo].[ConfiguracionHotel] ON;
;
SET IDENTITY_INSERT [dbo].[ConfiguracionHotel] OFF;

SET IDENTITY_INSERT [dbo].[Pisos] ON;
;
SET IDENTITY_INSERT [dbo].[Pisos] OFF;

SET IDENTITY_INSERT [dbo].[TiposHabitacion] ON;
;
SET IDENTITY_INSERT [dbo].[TiposHabitacion] OFF;

-- Estado: 0 Disponible, 2 Ocupada (reserva en curso), 3 En limpieza (salió ayer), 4 Fuera de servicio
SET IDENTITY_INSERT [dbo].[Habitaciones] ON;
;
SET IDENTITY_INSERT [dbo].[Habitaciones] OFF;

/* ---------------------------------------------------------------- 3. Huéspedes (en orden de alta) */
SET IDENTITY_INSERT [dbo].[Huespedes] ON;
;
;
SET IDENTITY_INSERT [dbo].[Huespedes] OFF;

/* ---------------------------------------------------------------- 4. Reservas
   Estado: 0 Confirmada, 1 En curso, 2 Finalizada, 3 Cancelada */
SET IDENTITY_INSERT [dbo].[Reservas] ON;
;
;
SET IDENTITY_INSERT [dbo].[Reservas] OFF;

/* ---------------------------------------------------------------- 5. Acompañantes (cargados en el check-in) */
;

/* ---------------------------------------------------------------- 6. Pagos
   MetodoPago: 0 Efectivo, 1 Tarjeta, 2 Transferencia */
SET IDENTITY_INSERT [dbo].[Pagos] ON;
;
;
SET IDENTITY_INSERT [dbo].[Pagos] OFF;

/* ---------------------------------------------------------------- 7. Bitácora de negocio (orden cronológico) */
;
;
;
;
;
;
;
;

/* ---------------------------------------------------------------- 8. Identidades: el próximo alta sigue la numeración */
DBCC CHECKIDENT ('[dbo].[ConfiguracionHotel]', RESEED, 1) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('[dbo].[Pisos]', RESEED, 4) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('[dbo].[TiposHabitacion]', RESEED, 6) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('[dbo].[Habitaciones]', RESEED, 19) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('[dbo].[Huespedes]', RESEED, 842) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('[dbo].[Reservas]', RESEED, 664) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('[dbo].[Pagos]', RESEED, 703) WITH NO_INFOMSGS;

COMMIT TRANSACTION;

PRINT 'Datos de negocio cargados. Recordá RECALCULAR los dígitos verificadores desde la aplicación.';
SELECT Estado, COUNT(*) AS Reservas, SUM(MontoTotal) AS Monto FROM Reservas GROUP BY Estado ORDER BY Estado;
GO
